CREATE TABLE IF NOT EXISTS "customers" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Login identity. 320 chars is the RFC 5321 maximum for an address.
	"email" VARCHAR(320) NOT NULL UNIQUE,
	-- Display name as entered by the customer.
	"full_name" VARCHAR(160) NOT NULL,
	-- E.164 phone number, used for delivery notifications.
	"phone" VARCHAR(32),
	-- Argon2id hash. Null for guest accounts that never set a password.
	"password_hash" VARCHAR(255),
	-- Explicit opt-in for marketing email.
	"accepts_marketing" BOOLEAN NOT NULL DEFAULT false,
	-- Account creation time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- Last profile change.
	"updated_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "customers" IS 'A person who can sign in and place orders. Guests are created here too, with a null password hash, so an order always has a customer row to hang off.';
COMMENT ON COLUMN "customers"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "customers"."email" IS 'Login identity. 320 chars is the RFC 5321 maximum for an address.';
COMMENT ON COLUMN "customers"."full_name" IS 'Display name as entered by the customer.';
COMMENT ON COLUMN "customers"."phone" IS 'E.164 phone number, used for delivery notifications.';
COMMENT ON COLUMN "customers"."password_hash" IS 'Argon2id hash. Null for guest accounts that never set a password.';
COMMENT ON COLUMN "customers"."accepts_marketing" IS 'Explicit opt-in for marketing email.';
COMMENT ON COLUMN "customers"."created_at" IS 'Account creation time.';
COMMENT ON COLUMN "customers"."updated_at" IS 'Last profile change.';

CREATE INDEX "idx_customers_created_at"
ON "customers" ("created_at");

CREATE TABLE IF NOT EXISTS "addresses" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owner of the address.
	"customer_id" BIGINT NOT NULL,
	-- Customer-facing nickname, e.g. "Home" or "Office".
	"label" VARCHAR(40),
	-- Street address, first line.
	"line1" VARCHAR(200) NOT NULL,
	-- Apartment, suite or building, when present.
	"line2" VARCHAR(200),
	-- City or locality.
	"city" VARCHAR(120) NOT NULL,
	-- State, province or region. Not all countries have one.
	"region" VARCHAR(120),
	-- Postal or ZIP code. Kept as text; leading zeros are significant.
	"postal_code" VARCHAR(24),
	-- ISO 3166-1 alpha-2 country code.
	"country_code" CHAR(2) NOT NULL,
	-- Preselected at checkout.
	"is_default" BOOLEAN NOT NULL DEFAULT false,
	-- Row creation time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "addresses" IS 'Address book entries. Orders never point at this table directly - they snapshot the address text, so editing an address later cannot rewrite delivery history.';
COMMENT ON COLUMN "addresses"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "addresses"."customer_id" IS 'Owner of the address.';
COMMENT ON COLUMN "addresses"."label" IS 'Customer-facing nickname, e.g. "Home" or "Office".';
COMMENT ON COLUMN "addresses"."line1" IS 'Street address, first line.';
COMMENT ON COLUMN "addresses"."line2" IS 'Apartment, suite or building, when present.';
COMMENT ON COLUMN "addresses"."city" IS 'City or locality.';
COMMENT ON COLUMN "addresses"."region" IS 'State, province or region. Not all countries have one.';
COMMENT ON COLUMN "addresses"."postal_code" IS 'Postal or ZIP code. Kept as text; leading zeros are significant.';
COMMENT ON COLUMN "addresses"."country_code" IS 'ISO 3166-1 alpha-2 country code.';
COMMENT ON COLUMN "addresses"."is_default" IS 'Preselected at checkout.';
COMMENT ON COLUMN "addresses"."created_at" IS 'Row creation time.';

CREATE INDEX "idx_addresses_customer_default"
ON "addresses" ("customer_id", "is_default");

CREATE TABLE IF NOT EXISTS "categories" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Parent category. Null for a top-level category.
	"parent_id" BIGINT,
	-- Display name.
	"name" VARCHAR(120) NOT NULL,
	-- URL segment, unique across the whole tree.
	"slug" VARCHAR(140) NOT NULL UNIQUE,
	-- Manual sort order among siblings.
	"position" INTEGER NOT NULL DEFAULT 0,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "categories" IS 'Self-referencing category tree (adjacency list). Deep trees are read with a recursive CTE; two or three levels is the norm for a storefront.';
COMMENT ON COLUMN "categories"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "categories"."parent_id" IS 'Parent category. Null for a top-level category.';
COMMENT ON COLUMN "categories"."name" IS 'Display name.';
COMMENT ON COLUMN "categories"."slug" IS 'URL segment, unique across the whole tree.';
COMMENT ON COLUMN "categories"."position" IS 'Manual sort order among siblings.';

CREATE TABLE IF NOT EXISTS "products" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Primary category for browsing. Null while a draft is being written.
	"category_id" BIGINT,
	-- Product title shown on the storefront.
	"name" VARCHAR(200) NOT NULL,
	-- URL segment for the product page.
	"slug" VARCHAR(220) NOT NULL UNIQUE,
	-- Long-form marketing copy, Markdown.
	"description" TEXT,
	-- draft | active | archived. Only active products are sellable.
	"status" VARCHAR(20) NOT NULL DEFAULT 'draft',
	-- Row creation time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- Last edit time.
	"updated_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "products" IS 'The sellable concept a shopper browses to ("Merino crew sweater"). It carries no price and no stock - those belong to variants.';
COMMENT ON COLUMN "products"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "products"."category_id" IS 'Primary category for browsing. Null while a draft is being written.';
COMMENT ON COLUMN "products"."name" IS 'Product title shown on the storefront.';
COMMENT ON COLUMN "products"."slug" IS 'URL segment for the product page.';
COMMENT ON COLUMN "products"."description" IS 'Long-form marketing copy, Markdown.';
COMMENT ON COLUMN "products"."status" IS 'draft | active | archived. Only active products are sellable.';
COMMENT ON COLUMN "products"."created_at" IS 'Row creation time.';
COMMENT ON COLUMN "products"."updated_at" IS 'Last edit time.';

CREATE INDEX "idx_products_status_category"
ON "products" ("status", "category_id");

CREATE TABLE IF NOT EXISTS "product_variants" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Parent product.
	"product_id" BIGINT NOT NULL,
	-- Stock keeping unit. The identifier warehouse and finance systems agree on.
	"sku" VARCHAR(64) NOT NULL UNIQUE,
	-- Resolved option map, e.g. {"size":"M","color":"navy"}. Kept denormalised for fast rendering.
	"option_values" JSON NOT NULL,
	-- Current list price in minor units. Integers only - never float money.
	"price_cents" INTEGER NOT NULL,
	-- ISO 4217 currency for price_cents.
	"currency_code" CHAR(3) NOT NULL DEFAULT 'USD',
	-- Shipping weight, used by rate calculators.
	"weight_grams" INTEGER,
	-- Hides a single variant without archiving the product.
	"is_active" BOOLEAN NOT NULL DEFAULT true,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "product_variants" IS 'The thing that actually has a price, a barcode and stock. Every product has at least one variant, even when the shopper never sees an option picker.';
COMMENT ON COLUMN "product_variants"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "product_variants"."product_id" IS 'Parent product.';
COMMENT ON COLUMN "product_variants"."sku" IS 'Stock keeping unit. The identifier warehouse and finance systems agree on.';
COMMENT ON COLUMN "product_variants"."option_values" IS 'Resolved option map, e.g. {"size":"M","color":"navy"}. Kept denormalised for fast rendering.';
COMMENT ON COLUMN "product_variants"."price_cents" IS 'Current list price in minor units. Integers only - never float money.';
COMMENT ON COLUMN "product_variants"."currency_code" IS 'ISO 4217 currency for price_cents.';
COMMENT ON COLUMN "product_variants"."weight_grams" IS 'Shipping weight, used by rate calculators.';
COMMENT ON COLUMN "product_variants"."is_active" IS 'Hides a single variant without archiving the product.';

CREATE INDEX "idx_variants_product_active"
ON "product_variants" ("product_id", "is_active");

CREATE TABLE IF NOT EXISTS "inventory_items" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Variant being stocked.
	"variant_id" BIGINT NOT NULL,
	-- Warehouse or store that holds the stock.
	"location_code" VARCHAR(40) NOT NULL,
	-- Units physically present.
	"on_hand" INTEGER NOT NULL DEFAULT 0,
	-- Units promised to open orders but not yet picked.
	"reserved" INTEGER NOT NULL DEFAULT 0,
	-- Level at which replenishment is triggered.
	"reorder_point" INTEGER,
	-- Last stock movement.
	"updated_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "inventory_items" IS 'Stock per variant per location. Sellable quantity is on_hand - reserved; keeping the two columns apart is what stops overselling during checkout.';
COMMENT ON COLUMN "inventory_items"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "inventory_items"."variant_id" IS 'Variant being stocked.';
COMMENT ON COLUMN "inventory_items"."location_code" IS 'Warehouse or store that holds the stock.';
COMMENT ON COLUMN "inventory_items"."on_hand" IS 'Units physically present.';
COMMENT ON COLUMN "inventory_items"."reserved" IS 'Units promised to open orders but not yet picked.';
COMMENT ON COLUMN "inventory_items"."reorder_point" IS 'Level at which replenishment is triggered.';
COMMENT ON COLUMN "inventory_items"."updated_at" IS 'Last stock movement.';

CREATE UNIQUE INDEX "uq_inventory_variant_location"
ON "inventory_items" ("variant_id", "location_code");

CREATE TABLE IF NOT EXISTS "carts" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owner once known. Null for an anonymous session.
	"customer_id" BIGINT,
	-- Anonymous cart identity stored in a cookie; merged into the customer cart at sign-in.
	"session_token" VARCHAR(64) NOT NULL UNIQUE,
	-- Currency the cart is priced in.
	"currency_code" CHAR(3) NOT NULL DEFAULT 'USD',
	-- Cart creation time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- When an abandoned cart may be reaped.
	"expires_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "carts" IS 'A short-lived basket. Carts are disposable: nothing downstream reads them after an order is placed.';
COMMENT ON COLUMN "carts"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "carts"."customer_id" IS 'Owner once known. Null for an anonymous session.';
COMMENT ON COLUMN "carts"."session_token" IS 'Anonymous cart identity stored in a cookie; merged into the customer cart at sign-in.';
COMMENT ON COLUMN "carts"."currency_code" IS 'Currency the cart is priced in.';
COMMENT ON COLUMN "carts"."created_at" IS 'Cart creation time.';
COMMENT ON COLUMN "carts"."expires_at" IS 'When an abandoned cart may be reaped.';

CREATE TABLE IF NOT EXISTS "cart_items" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Parent cart.
	"cart_id" BIGINT NOT NULL,
	-- Variant added to the cart.
	"variant_id" BIGINT NOT NULL,
	-- Units requested.
	"quantity" INTEGER NOT NULL DEFAULT 1,
	-- When the line was added; drives "recently added" UI.
	"added_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "cart_items" IS 'Cart lines deliberately store no price. The cart re-reads the live variant price on every render, which is why a price change is visible before checkout.';
COMMENT ON COLUMN "cart_items"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "cart_items"."cart_id" IS 'Parent cart.';
COMMENT ON COLUMN "cart_items"."variant_id" IS 'Variant added to the cart.';
COMMENT ON COLUMN "cart_items"."quantity" IS 'Units requested.';
COMMENT ON COLUMN "cart_items"."added_at" IS 'When the line was added; drives "recently added" UI.';

CREATE UNIQUE INDEX "uq_cart_items_cart_variant"
ON "cart_items" ("cart_id", "variant_id");

CREATE TABLE IF NOT EXISTS "orders" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Who placed the order.
	"customer_id" BIGINT NOT NULL,
	-- Human-facing reference printed on invoices and used by support.
	"order_number" VARCHAR(32) NOT NULL UNIQUE,
	-- pending | paid | fulfilled | cancelled | refunded.
	"status" VARCHAR(24) NOT NULL DEFAULT 'pending',
	-- Currency the totals are denominated in.
	"currency_code" CHAR(3) NOT NULL,
	-- Sum of line totals before shipping and tax.
	"subtotal_cents" INTEGER NOT NULL,
	-- Shipping charged, in minor units.
	"shipping_cents" INTEGER NOT NULL DEFAULT 0,
	-- Tax charged, in minor units.
	"tax_cents" INTEGER NOT NULL DEFAULT 0,
	-- Amount authorised against the payment method.
	"total_cents" INTEGER NOT NULL,
	-- Snapshot of the delivery address at purchase time.
	"shipping_address" JSON NOT NULL,
	-- Snapshot of the billing address when it differs.
	"billing_address" JSON,
	-- Checkout completion time.
	"placed_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- Set when the order is cancelled; kept rather than deleting the row.
	"cancelled_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "orders" IS 'The financial record of a purchase. Everything a receipt must still show years later is snapshotted here rather than joined at read time.';
COMMENT ON COLUMN "orders"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "orders"."customer_id" IS 'Who placed the order.';
COMMENT ON COLUMN "orders"."order_number" IS 'Human-facing reference printed on invoices and used by support.';
COMMENT ON COLUMN "orders"."status" IS 'pending | paid | fulfilled | cancelled | refunded.';
COMMENT ON COLUMN "orders"."currency_code" IS 'Currency the totals are denominated in.';
COMMENT ON COLUMN "orders"."subtotal_cents" IS 'Sum of line totals before shipping and tax.';
COMMENT ON COLUMN "orders"."shipping_cents" IS 'Shipping charged, in minor units.';
COMMENT ON COLUMN "orders"."tax_cents" IS 'Tax charged, in minor units.';
COMMENT ON COLUMN "orders"."total_cents" IS 'Amount authorised against the payment method.';
COMMENT ON COLUMN "orders"."shipping_address" IS 'Snapshot of the delivery address at purchase time.';
COMMENT ON COLUMN "orders"."billing_address" IS 'Snapshot of the billing address when it differs.';
COMMENT ON COLUMN "orders"."placed_at" IS 'Checkout completion time.';
COMMENT ON COLUMN "orders"."cancelled_at" IS 'Set when the order is cancelled; kept rather than deleting the row.';

CREATE INDEX "idx_orders_customer_placed"
ON "orders" ("customer_id", "placed_at");
CREATE INDEX "idx_orders_status"
ON "orders" ("status");

CREATE TABLE IF NOT EXISTS "order_items" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Parent order.
	"order_id" BIGINT NOT NULL,
	-- Variant sold. Nullable so a discontinued variant can be hard-deleted without destroying order history.
	"variant_id" BIGINT,
	-- SKU snapshot at purchase time.
	"sku" VARCHAR(64) NOT NULL,
	-- Product name snapshot, exactly as shown on the receipt.
	"name" VARCHAR(200) NOT NULL,
	-- Units ordered.
	"quantity" INTEGER NOT NULL,
	-- Price per unit at purchase time. Never re-read from the variant.
	"unit_price_cents" INTEGER NOT NULL,
	-- quantity * unit_price_cents, stored so line arithmetic is auditable.
	"total_cents" INTEGER NOT NULL,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "order_items" IS 'Immutable order lines. The snapshot columns are what make an order reproducible after the catalog moves on.';
COMMENT ON COLUMN "order_items"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "order_items"."order_id" IS 'Parent order.';
COMMENT ON COLUMN "order_items"."variant_id" IS 'Variant sold. Nullable so a discontinued variant can be hard-deleted without destroying order history.';
COMMENT ON COLUMN "order_items"."sku" IS 'SKU snapshot at purchase time.';
COMMENT ON COLUMN "order_items"."name" IS 'Product name snapshot, exactly as shown on the receipt.';
COMMENT ON COLUMN "order_items"."quantity" IS 'Units ordered.';
COMMENT ON COLUMN "order_items"."unit_price_cents" IS 'Price per unit at purchase time. Never re-read from the variant.';
COMMENT ON COLUMN "order_items"."total_cents" IS 'quantity * unit_price_cents, stored so line arithmetic is auditable.';

CREATE INDEX "idx_order_items_order"
ON "order_items" ("order_id");

CREATE TABLE IF NOT EXISTS "payments" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Order being paid.
	"order_id" BIGINT NOT NULL,
	-- Gateway that processed the charge, e.g. stripe or adyen.
	"provider" VARCHAR(40) NOT NULL,
	-- Gateway charge id. Unique, so a replayed webhook cannot double-record a payment.
	"provider_reference" VARCHAR(120) NOT NULL UNIQUE,
	-- authorized | captured | failed | refunded.
	"status" VARCHAR(24) NOT NULL,
	-- Amount moved, in minor units. Negative for a refund.
	"amount_cents" INTEGER NOT NULL,
	-- Currency of amount_cents.
	"currency_code" CHAR(3) NOT NULL,
	-- When the gateway event was recorded.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "payments" IS 'One row per money movement, not one per order. Partial captures, retries and refunds all append rows, so the order total and the sum of payments can be reconciled.';
COMMENT ON COLUMN "payments"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "payments"."order_id" IS 'Order being paid.';
COMMENT ON COLUMN "payments"."provider" IS 'Gateway that processed the charge, e.g. stripe or adyen.';
COMMENT ON COLUMN "payments"."provider_reference" IS 'Gateway charge id. Unique, so a replayed webhook cannot double-record a payment.';
COMMENT ON COLUMN "payments"."status" IS 'authorized | captured | failed | refunded.';
COMMENT ON COLUMN "payments"."amount_cents" IS 'Amount moved, in minor units. Negative for a refund.';
COMMENT ON COLUMN "payments"."currency_code" IS 'Currency of amount_cents.';
COMMENT ON COLUMN "payments"."created_at" IS 'When the gateway event was recorded.';

CREATE INDEX "idx_payments_order_status"
ON "payments" ("order_id", "status");

CREATE TABLE IF NOT EXISTS "shipments" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Order being shipped.
	"order_id" BIGINT NOT NULL,
	-- Carrier name, e.g. UPS or DHL.
	"carrier" VARCHAR(60) NOT NULL,
	-- Carrier tracking number, once assigned.
	"tracking_number" VARCHAR(80),
	-- pending | in_transit | delivered | returned.
	"status" VARCHAR(24) NOT NULL DEFAULT 'pending',
	-- Handover to the carrier.
	"shipped_at" TIMESTAMP,
	-- Confirmed delivery time.
	"delivered_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "shipments" IS 'A parcel. An order can produce several shipments when stock comes from different locations, which is why this is not a set of columns on orders.';
COMMENT ON COLUMN "shipments"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "shipments"."order_id" IS 'Order being shipped.';
COMMENT ON COLUMN "shipments"."carrier" IS 'Carrier name, e.g. UPS or DHL.';
COMMENT ON COLUMN "shipments"."tracking_number" IS 'Carrier tracking number, once assigned.';
COMMENT ON COLUMN "shipments"."status" IS 'pending | in_transit | delivered | returned.';
COMMENT ON COLUMN "shipments"."shipped_at" IS 'Handover to the carrier.';
COMMENT ON COLUMN "shipments"."delivered_at" IS 'Confirmed delivery time.';

CREATE INDEX "idx_shipments_order_status"
ON "shipments" ("order_id", "status");

ALTER TABLE "addresses"
ADD FOREIGN KEY("customer_id") REFERENCES "customers"("id")
ON UPDATE CASCADE ON DELETE CASCADE;
ALTER TABLE "categories"
ADD FOREIGN KEY("parent_id") REFERENCES "categories"("id")
ON UPDATE CASCADE ON DELETE SET NULL;
ALTER TABLE "products"
ADD FOREIGN KEY("category_id") REFERENCES "categories"("id")
ON UPDATE CASCADE ON DELETE SET NULL;
ALTER TABLE "product_variants"
ADD FOREIGN KEY("product_id") REFERENCES "products"("id")
ON UPDATE CASCADE ON DELETE CASCADE;
ALTER TABLE "inventory_items"
ADD FOREIGN KEY("variant_id") REFERENCES "product_variants"("id")
ON UPDATE CASCADE ON DELETE CASCADE;
ALTER TABLE "carts"
ADD FOREIGN KEY("customer_id") REFERENCES "customers"("id")
ON UPDATE CASCADE ON DELETE SET NULL;
ALTER TABLE "cart_items"
ADD FOREIGN KEY("cart_id") REFERENCES "carts"("id")
ON UPDATE CASCADE ON DELETE CASCADE;
ALTER TABLE "cart_items"
ADD FOREIGN KEY("variant_id") REFERENCES "product_variants"("id")
ON UPDATE CASCADE ON DELETE CASCADE;
ALTER TABLE "orders"
ADD FOREIGN KEY("customer_id") REFERENCES "customers"("id")
ON UPDATE CASCADE ON DELETE RESTRICT;
ALTER TABLE "order_items"
ADD FOREIGN KEY("order_id") REFERENCES "orders"("id")
ON UPDATE CASCADE ON DELETE CASCADE;
ALTER TABLE "order_items"
ADD FOREIGN KEY("variant_id") REFERENCES "product_variants"("id")
ON UPDATE CASCADE ON DELETE SET NULL;
ALTER TABLE "payments"
ADD FOREIGN KEY("order_id") REFERENCES "orders"("id")
ON UPDATE CASCADE ON DELETE RESTRICT;
ALTER TABLE "shipments"
ADD FOREIGN KEY("order_id") REFERENCES "orders"("id")
ON UPDATE CASCADE ON DELETE CASCADE;
